        child: Container(
          decoration: BoxDecoration(
            color: GoOutsColors.cardSurface,
            borderRadius: BorderRadius.circular(12),
            border: Border.all(
              color: highlighted
                  ? GoOutsColors.primaryBlue
                  : Colors.transparent,
              width: 2,
            ),
            boxShadow: const <BoxShadow>[
              BoxShadow(
                color: GoOutsColors.cardShadow,
                blurRadius: 10,
                offset: Offset(0, 3),
              ),
            ],
          ),
          clipBehavior: Clip.antiAlias,
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: <Widget>[
              Stack(
                children: <Widget>[
                  cover.isEmpty
                      ? Container(
                          height: 170,
                          width: double.infinity,
                          color: GoOutsColors.dividerGray,
                          child: const Icon(Icons.home_outlined,
                              size: 36, color: GoOutsColors.outlineVariant),
                        )
                      : Image.network(
                          cover,
                          height: 170,
                          width: double.infinity,
                          fit: BoxFit.cover,
                          cacheWidth: 640,
                          errorBuilder: (_, __, ___) => Container(
                            height: 170,
                            color: GoOutsColors.dividerGray,
                            child: const Icon(Icons.broken_image_outlined,
                                color: GoOutsColors.outlineVariant),
                          ),
                        ),
                  if (l.ratingCount > 0)
                    Positioned(
                      left: 10,
                      top: 10,
                      child: _photoChip(
                        '${l.ratingAvg.toStringAsFixed(1)} (${l.ratingCount})',
                        colour: Colors.black.withValues(alpha: 0.6),
                        icon: Icons.star,
                      ),
                    ),
                  Positioned(right: 10, top: 10, child: _saveButton(l)),
                ],
              ),
              Padding(
                padding: const EdgeInsets.fromLTRB(14, 12, 14, 14),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: <Widget>[
